{"command": "cd /workspace && python3 - <<'PY'
import subprocess, wave, numpy as np

def run(args):
    return subprocess.run(args, shell=True, capture_output=True, text=True)

run('ft2 call pattern_set_length \'{"pattern":0,"rows":16}\'')
run('ft2 call pattern_clear \'{"pattern":0}\'')
run('ft2 call pattern_set_cell \'{"pattern":0,"row":0,"channel":0,"note":"C-4","instrument":10,"volume":64}\'')
for r in range(1,16):
    run(f'ft2 call pattern_set_cell \'{{"pattern":0,"row":{r},"channel":0,"effect":10,"effect_param":15}}\'')
run('ft2 call module_render \'{"path":"test_vs2.wav","loops":0}\'')
w=wave.open('test_vs2.wav','rb')
data=np.frombuffer(w.readframes(w.getnframes()),dtype=np.int16)
for r in range(16):
    seg=data[int(r*44100*0.1667):int((r+1)*44100*0.1667)]
    print(r, np.sqrt(np.mean(seg.astype(np.float64)**2)))
PY"}

